def f(value, src, note=""):
    t, u, k = S[src]
    return {"value": value, "source_title": t, "source_url": u, "source_type": k, "checked": CHECKED, "note": note}

def blank(note=""):
    return {"value": None, "source_title": "", "source_url": "", "source_type": "", "checked": CHECKED, "note": note}

