def club(slug, name, short, ground, cap, cap_note, st_min, st_max, md_min, md_max, pint, pie, prog, notes=""):
    return {"slug": slug, "name": name, "short_name": short, "league": "Premier League", "season": "2026/27",
            "stadium": f(ground, "wiki", ""), "capacity": f(cap, "wiki", cap_note),
            "season_ticket_min": st_min, "season_ticket_max": st_max,
            "matchday_min": md_min, "matchday_max": md_max,
            "away_ticket": AWAY(), "pint": pint, "pie": pie, "programme": prog, "notes": notes}

